<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$codigo=trim($_GET['codigo']??'');$ir_perfil=($_GET['perfil']??'')==='1';$stmt=$mysqli->prepare("SELECT a.id,a.link_url,p.id perfil_id FROM anuncios_profissionais a JOIN profissionais p ON p.id=a.profissional_id WHERE a.codigo=? AND a.status='aprovado' LIMIT 1");$stmt->bind_param('s',$codigo);$stmt->execute();$ad=$stmt->get_result()->fetch_assoc();if(!$ad)redirecionar('/');$tipo=$ir_perfil?'perfil':'clique';$uid=usuario_autenticado()?(int)$_SESSION['usuario_id']:null;$stmt=$mysqli->prepare('INSERT INTO eventos_anuncios(anuncio_id,usuario_id,tipo) VALUES(?,?,?)');$stmt->bind_param('iis',$ad['id'],$uid,$tipo);$stmt->execute();$destino=$ir_perfil||empty($ad['link_url'])?'/profissional.php?id='.(int)$ad['perfil_id']:$ad['link_url'];redirecionar($destino);
